package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.study.StudyOperationExecutor.Context;
import org.jlinalg.study.StudyOperationExecutor.State;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StudyGwasEnrichmentTest {
    @TempDir Path root;
    private Map<String,Object> policy()throws Exception{
        for(String file:List.of("summary.tsv","ld-scores.tsv","annotations.tsv","overlap.tsv"))Files.copy(Path.of("src/test/resources/sldsc").resolve(file),root.resolve(file));
        var s=new LinkedHashMap<String,Object>(Map.of("file","summary.tsv","coverage","complete","tested_snps",483,"population","synthetic","genome_build","GRCh38","calibration","one_df_chi_square","model","synthetic numerical reference","qc","full synthetic input; numerical verification only","ascertainment","quantitative"));
        return new LinkedHashMap<>(Map.of("summary",s,"reference",Map.of("population","synthetic","genome_build","GRCh38","release","fixture-1","common_variant_definition","binary synthetic reference annotations","regression_snp_definition","all 483 synthetic reference rows","annotation_model","all + two overlapping targets + nuisance"),"ld_scores","ld-scores.tsv","annotations","annotations.tsv","overlap","overlap.tsv","blocks",13,"minimum_snps",100,"minimum_chromosomes",20,"adjustment","BY"));
    }
    private Context context(String folder,Map<String,Object> p)throws Exception{return new Context(root,Files.createDirectory(root.resolve(folder)),Map.of("id",folder,"type","gwas_enrichment","hypothesis","H","datasets",List.of()),Map.of("resources",Map.of("directory","fixture-resources","network","offline","downloads","deny"),"datasets",List.of(),"hypotheses",List.of(Map.of("id","H","analysis",Map.of("gwas_enrichment",p)))),Map.of(),Map.of());}
    private static void seal(Context c,org.jlinalg.study.StudyOperationExecutor.Result r)throws Exception{var hashes=new LinkedHashMap<String,Object>();try(var paths=Files.walk(c.outputDirectory())){for(Path f:paths.filter(Files::isRegularFile).toList())hashes.put(c.outputDirectory().relativize(f).toString().replace('\\','/'),FollowupSupport.hash(f));}StudyPublicEvidence.write(c.outputDirectory().resolve("manifest.yaml"),Map.of("operation_id",c.operation().get("id"),"operation_type",c.operation().get("type"),"hypothesis","H","state",r.state().value(),"details",r.details(),"output_sha256",hashes));}
    @Test void nativeEnrichmentUsesAllTargetsAndRetainsReferenceAndCovarianceEvidence()throws Exception{
        var p=policy();var c=context("native",p);var r=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,r.state(),r.summary());assertEquals(true,r.details().get("official_family_complete"));var table=DelimitedData.readResult(c.outputDirectory().resolve("gwas-enrichment.tsv"));assertEquals(2,table.rows().size());assertEquals(483,r.details().get("regression_snps"));
        for(String[] row:table.rows()){double probability=Double.parseDouble(row[table.column("p_value")]),q=Double.parseDouble(row[table.column("adjusted_p")]);assertEquals("ok",row[table.column("status")]);assertTrue(q>=probability);assertEquals("BY",row[table.column("adjustment")]);}
        assertEquals(52,DelimitedData.readResult(c.outputDirectory().resolve("sldsc-block-deletes.tsv")).rows().size());assertEquals(16,DelimitedData.readResult(c.outputDirectory().resolve("sldsc-coefficient-covariance.tsv")).rows().size());seal(c,r);
        var inventory=new Context(root,Files.createDirectory(root.resolve("inventory")),Map.of("type","finding_inventory","scope","study","datasets",List.of()),c.study(),Map.of(),Map.of("native",c.outputDirectory()));new StudyFindingInventory().execute(inventory);var lines=Files.readAllLines(inventory.outputDirectory().resolve("finding-inventory.jsonl"));assertEquals(2,lines.size());for(String line:lines){assertTrue(line.contains("enrichment_se"));assertTrue(line.contains("observed-scale"));assertTrue(line.contains("BY"));assertFalse(line.contains("sldsc-coefficients.tsv"));assertTrue(line.contains("gwas_enrichment_context"));assertTrue(line.contains("total_heritability_z"));assertFalse(line.contains("ld-scores.tsv"));assertFalse(line.contains("summary.tsv"));}
    }
    @Test void weakHeritabilityAndWorkLimitsDoNotCreateAnOfficialAdjustedFamily()throws Exception{
        var p=policy();var lines=Files.readAllLines(root.resolve("summary.tsv"));for(int i=1;i<lines.size();i++){String[] r=lines.get(i).split("\t");r[5]="1";lines.set(i,String.join("\t",r));}Files.write(root.resolve("summary.tsv"),lines);var c=context("weak",p);var r=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,r.state(),r.summary());assertEquals(false,r.details().get("official_family_complete"));
        if(Files.exists(c.outputDirectory().resolve("gwas-enrichment.tsv"))){var table=DelimitedData.readResult(c.outputDirectory().resolve("gwas-enrichment.tsv"));for(String[] row:table.rows())assertEquals("NA",row[table.column("adjusted_p")]);}
        p.put("maximum_work",1);assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(context("budget",p)).state());
    }
    @Test void selectedIncompleteMismatchedOrMissingInputsWaitBeforeInference()throws Exception{
        var p=policy();var s=StudyPublicEvidence.map(p.get("summary"));s.put("coverage","selected_only");p.put("summary",s);assertTrue(new StudyCliExecutor().execute(context("selected",p)).summary().contains("complete GWAS"));s.put("coverage","complete");s.put("tested_snps",484);assertTrue(new StudyCliExecutor().execute(context("count",p)).summary().contains("row count"));s.put("tested_snps",483);s.put("population","other");assertTrue(new StudyCliExecutor().execute(context("ancestry",p)).summary().contains("population/build"));s.put("population","synthetic");p.put("overlap","missing.tsv");var r=new StudyCliExecutor().execute(context("missing",p));assertEquals(State.WAITING_FOR_INPUT,r.state());assertTrue(r.summary().contains("overlap"));
    }
    @Test void qcExclusionsRetainReasonsAndMissingCoverageNeverBecomesANull()throws Exception{
        var p=policy();var lines=Files.readAllLines(root.resolve("summary.tsv"));for(int i=1;i<70;i++){String[] r=lines.get(i).split("\t");r[3]="C";lines.set(i,String.join("\t",r));}Files.write(root.resolve("summary.tsv"),lines);var c=context("coverage",p);var r=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,r.state());assertTrue(r.summary().contains("coverage"));assertFalse(Files.exists(c.outputDirectory().resolve("gwas-enrichment.tsv")));assertEquals(69,DelimitedData.readResult(c.outputDirectory().resolve("snp-qc-exclusions.tsv")).rows().size());
    }
    @Test void contentChangesAlterCacheIdentityAndCsvSourcesRemainParseable()throws Exception{
        var p=policy();var c=context("cache",p);var before=StudyGwasEnrichmentResources.inputHashes(root,c.study(),c.operation());Files.writeString(root.resolve("annotations.tsv"),Files.readString(root.resolve("annotations.tsv")).replace("Synthetic TARGET_A","Edited TARGET_A"));var after=StudyGwasEnrichmentResources.inputHashes(root,c.study(),c.operation());assertNotEquals(before.get("gwas_enrichment:annotations"),after.get("gwas_enrichment:annotations"));assertEquals(before.get("gwas_enrichment:overlap"),after.get("gwas_enrichment:overlap"));Files.writeString(root.resolve("summary.csv"),Files.readString(root.resolve("summary.tsv")).replace('\t',','));var s=StudyPublicEvidence.map(p.get("summary"));s.put("file","summary.csv");p.put("summary",s);assertEquals(State.COMPLETE,new StudyCliExecutor().execute(context("csv",p)).state());
    }
    @Test void summaryOnlyStudyRunsAndReplaysWithoutAssociationOrMetaAnalysis()throws Exception{
        var p=policy();var study=Map.of("schema_version",1,"project",Map.of("id","sldsc-only","title","Synthetic S-LDSC","description","Numerical verification of a complete summary branch"),"resources",Map.of("directory","fixture-resources","network","offline","downloads","deny"),"datasets",List.of(),"hypotheses",List.of(Map.of("id","H","description","Complete LD-aware functional annotation enrichment","analysis",Map.of("mode","manual","goals",List.of("gwas_enrichment"),"gwas_enrichment",p))));StudyPublicEvidence.write(root.resolve("study.json"),study);var errors=new ByteArrayOutputStream();
        for(int i=0;i<2;i++)assertEquals(0,JLinAlgCli.run(new String[]{"study","auto",root.resolve("study.json").toString(),"--offline","--actor-type","external","--actor-id","synthetic-reference"},new PrintStream(new ByteArrayOutputStream()),new PrintStream(errors)),errors.toString());
        var status=StudyYaml.loadArtifact(root.resolve("state/project-status.yaml"));assertEquals("completed",status.get("state"));Path run=root.resolve("runs").resolve(String.valueOf(status.get("run_id"))).resolve("operations");try(var paths=Files.list(run)){for(Path folder:paths.toList()){var manifest=StudyYaml.loadArtifact(folder.resolve("manifest.yaml"));assertEquals(true,manifest.get("reused_from_cache"));assertFalse(SetHolder.REFITS.contains(manifest.get("operation_type")));}}
        assertEquals(0,JLinAlgCli.run(new String[]{"study","verify","--project",root.toString()},new PrintStream(new ByteArrayOutputStream()),new PrintStream(errors)),errors.toString());
    }
    @Test void suppliedEnrichmentSatisfiesTheGoalWithoutRefittingOrRequiringLdFiles()throws Exception{
        var p=policy();var nativeContext=context("source",p);var nativeResult=new StudyCliExecutor().execute(nativeContext);assertEquals(State.COMPLETE,nativeResult.state());Files.copy(nativeContext.outputDirectory().resolve("gwas-enrichment.tsv"),root.resolve("external.tsv"));
        var supplied=Map.of("id","external","kind","gwas_enrichment","files",Map.of("results","external.tsv"),"scope",Map.of("species","human","genome_build","GRCh38","ancestry","synthetic","modality","gwas"),"method",Map.of("name","External synthetic S-LDSC"),"family",Map.of("id","external-targets","coverage","complete","tested_count",2,"adjustment","BY","adjusted_p_from_full_family",true));
        var analysis=Map.of("mode","manual","goals",List.of("gwas_enrichment"),"supplied_results",List.of(supplied));var study=Map.of("schema_version",1,"project",Map.of("id","reuse","title","Reuse complete GWAS enrichment","description","External numerical fixture"),"datasets",List.of(),"hypotheses",List.of(Map.of("id","H","description","Reuse supplied stage","analysis",analysis)));StudyPublicEvidence.write(root.resolve("supplied.json"),study);
        var resolved=org.jlinalg.study.StudyResolver.resolve(root.resolve("supplied.json"));var plan=org.jlinalg.study.StudyPlanner.compile(resolved);var operations=StudyPublicEvidence.list(plan.document().get("operations")).stream().map(StudyPublicEvidence::map).filter(op->"gwas_enrichment".equals(op.get("type"))).toList();assertEquals(1,operations.size());assertEquals("external",operations.get(0).get("supplied_result_id"));
        var c=new Context(root,Files.createDirectory(root.resolve("supplied")),operations.get(0),resolved.document(),plan.document(),Map.of());var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state());assertEquals(false,result.details().get("analysis_executed_by_jlinalg"));var table=DelimitedData.readResult(c.outputDirectory().resolve("gwas-enrichment.tsv"));assertTrue(table.header().contains("enrichment_se"));assertEquals(2,table.rows().size());assertFalse(Files.exists(c.outputDirectory().resolve("ld-scores.tsv")));
    }
    @Test void completeOfficialMetaCanSupplyWaldStatisticsWithExplicitCalibrationAndNoAssociationRefit()throws Exception{
        var p=policy();var s=StudyPublicEvidence.map(p.get("summary"));s.remove("file");s.put("statistic","beta_se");p.put("summary",s);
        var input=Files.readAllLines(root.resolve("summary.tsv"));var rows=new java.util.ArrayList<String>();rows.add("feature_id\tbeta\tse\tp_value\tn\tchromosome\tposition\tref\talt");
        for(String line:input.subList(1,input.size())){String[] r=line.split("\t");double z=Math.sqrt(Double.parseDouble(r[5]));rows.add(r[0]+"\t"+z+"\t1\t"+org.jlinalg.xwas.SummaryMath.p(z)+"\t"+r[6]+"\t"+r[1]+"\t"+r[2]+"\t"+r[3]+"\t"+r[4]);}Files.write(root.resolve("meta.tsv"),rows);
        var definition=Map.of("id","meta","kind","meta_analysis","files",Map.of("results","meta.tsv"),"scope",Map.of("genome_build","GRCh38"),"method",Map.of("name","Synthetic complete Wald meta-analysis"),"family",Map.of("id","all-snps","coverage","complete","tested_count",483,"adjustment","BH"));
        Map<String,Object> study=Map.of("datasets",List.of(),"hypotheses",List.of(Map.of("id","H","analysis",Map.of("gwas_enrichment",p,"supplied_results",List.of(definition)))));var imported=new Context(root,Files.createDirectory(root.resolve("meta")),Map.of("id","meta","type","meta_analysis","hypothesis","H","supplied_result_id","meta"),study,Map.of(),Map.of());var ir=new StudyCliExecutor().execute(imported);assertEquals(State.COMPLETE,ir.state());seal(imported,ir);
        var c=new Context(root,Files.createDirectory(root.resolve("official")),Map.of("id","official","type","gwas_enrichment","hypothesis","H","datasets",List.of()),study,Map.of(),Map.of("meta",imported.outputDirectory()));var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals("official_scoped_results",result.details().get("source_origin"));assertEquals(483,result.details().get("regression_snps"));assertTrue(result.details().containsKey("primary_selection"));
    }
    @Test void reversedCodingWithAnotherIdCannotDuplicateAPhysicalReferenceSnp()throws Exception{
        var p=policy();var lines=Files.readAllLines(root.resolve("ld-scores.tsv"));String[] duplicate=lines.get(1).split("\t");duplicate[0]="another-name";duplicate[3]="G";duplicate[4]="A";lines.add(String.join("\t",duplicate));Files.write(root.resolve("ld-scores.tsv"),lines);var c=context("duplicate-alleles",p);var result=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertTrue(result.summary().contains("reversed coding"));assertFalse(Files.exists(c.outputDirectory().resolve("gwas-enrichment.tsv")));
    }
    private static final class SetHolder {private static final java.util.Set<String> REFITS=java.util.Set.of("association","participant_qc","meta_analysis");}
}
